var helpers=require("./helpers"),should=require("should"),sinon=require("sinon"),utils=require("./../lib/utils");describe("utils.should_proxy_to()",function(){var e=utils.should_proxy_to,s=".ic1.mycorp,localhost,127.0.0.1,*.mycorp.org",t=" ,.mycorp.org:1234,.ic1.mycorp,localhost,127.0.0.1",o="http://registry.random.opr.mycorp.org",r="http://registry.random.opr.mycorp.org:9874",n="http://127.0.0.1";it("returns true if NO_PROXY is undefined",function(s){process.env.NO_PROXY=void 0,e(o).should.true(),delete process.env.NO_PROXY,s()}),it("returns true if NO_PROXY is empty",function(s){process.env.NO_PROXY="",e(o).should.true(),delete process.env.NO_PROXY,s()}),it("returns false if NO_PROXY is a wildcard",function(s){process.env.NO_PROXY="*",e(o).should.false(),delete process.env.NO_PROXY,s()}),it("returns true if the host matches and the ports don't (URI doesn't have port specified)",function(s){process.env.NO_PROXY=t,e(o).should.true(),delete process.env.NO_PROXY,s()}),it("returns true if the host matches and the ports don't (both have a port specified but just different values)",function(s){process.env.NO_PROXY=t,e(r).should.true(),delete process.env.NO_PROXY,s()}),it("returns false if the host matches and the ports don't (no_proxy pattern doesn't have a port)",function(t){process.env.NO_PROXY=s,e(r).should.false(),delete process.env.NO_PROXY,t()}),it("returns false if host matches",function(t){process.env.NO_PROXY=s,e(o).should.false(),delete process.env.NO_PROXY,t()}),it("returns false if the host and port matches",function(s){process.env.NO_PROXY=t,e("http://registry.random.opr.mycorp.org:1234").should.false(),delete process.env.NO_PROXY,s()}),it("returns false if the host matches (localhost)",function(t){process.env.NO_PROXY=s,e("http://localhost").should.false(),delete process.env.NO_PROXY,t()}),it("returns false if the host matches (ip)",function(t){process.env.NO_PROXY=s,e(n).should.false(),delete process.env.NO_PROXY,t()}),it("returns false if the host matches (ip)",function(t){process.env.NO_PROXY=s.replace(/,g/," "),e(n).should.false(),delete process.env.NO_PROXY,t()}),it("returns false if the host matches (ip)",function(t){process.env.NO_PROXY=s.replace(/,g/," "),e(n).should.false(),delete process.env.NO_PROXY,t()})});